package com.ias.ticket;
import com.ias.trust.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;
import java.sql.Timestamp;
import java.time.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Current assignment is the only engineer object grant. Inbox/receipt is a separate narrow projection. */
@RestController
public class Transfers {
 final Tickets t;final StaffAccess access;
 public Transfers(Tickets t,StaffAccess access){this.t=t;this.access=access;}
 static Problem conflict(String c){return new Problem(409,c);}
 static boolean active(Map<String,Object>r){return Set.of("ASSIGNED","IN_PROGRESS").contains(r.get("status"))&&r.get("assignment_id")!=null;}
 static String stable(String value){return UUID.nameUUIDFromBytes(value.getBytes(StandardCharsets.UTF_8)).toString();}
 Instant now(){return new Completion(t,access).now();}
 Map<String,Object> current(Map<String,Object>r,boolean lock){if(r.get("current_transfer_id")==null)return null;var rows=t.db.queryForList("SELECT * FROM ticket_transfer_request WHERE id=? AND ticket_id=? AND round_id=?"+(lock?" FOR UPDATE":""),r.get("current_transfer_id"),r.get("id"),r.get("round_id"));if(rows.isEmpty())throw conflict("TRANSFER_NOT_CURRENT");return rows.getFirst();}
 Map<String,Object> request(Object id){var rows=t.db.queryForList("SELECT * FROM ticket_transfer_request WHERE id=?",id);if(rows.isEmpty())throw new Problem(404,"TARGET_NOT_ACCESSIBLE");return rows.getFirst();}
 Map<String,Object> end(Object id){var rows=t.db.queryForList("SELECT * FROM ticket_transfer_end WHERE request_id=?",id);return rows.isEmpty()?null:rows.getFirst();}
 boolean due(Map<String,Object>q,Instant time){return !time.isBefore(Completion.instant(q.get("expires_at")));}
 boolean selfQualified(Map<String,Object>f,Object department){return Boolean.TRUE.equals(f.get("enabled"))&&Boolean.TRUE.equals(f.get("departmentEnabled"))&&department.toString().equals(f.get("departmentId"))&&((List<?>)f.get("permissions")).containsAll(List.of("ticket.engineer.read","ticket.assignment.accept","ticket.record"));}
 boolean receivable(Map<String,Object>f,Object dept){return Boolean.TRUE.equals(f.get("enabled"))&&Boolean.TRUE.equals(f.get("departmentEnabled"))&&dept.toString().equals(f.get("departmentId"))&&((List<?>)f.get("permissions")).containsAll(List.of("ticket.engineer.read","ticket.assignment.accept"));}
 void recipient(Map<String,Object>q,Tickets.Actor a,Map<String,Object>f){if(Tickets.id(q.get("tenant_id"))!=a.tenant()||Tickets.id(q.get("target_engineer_user_id"))!=a.user())throw new Problem(404,"TARGET_NOT_ACCESSIBLE");if(!receivable(f,q.get("target_department_id")))throw new Problem(403,"ACCESS_DENIED");}
 boolean sourceQualified(Map<String,Object>row){long deadline=System.currentTimeMillis()+2000;var f=Chain.call("ticket-identity","/internal/identity/ticket-authorizations",Map.of("purpose","TRANSFER_SYSTEM","tenantId",row.get("tenant_id").toString(),"targetUserId",row.get("engineer_user_id").toString(),"departmentId",row.get("department_id").toString()),UUID.randomUUID().toString(),deadline);Chain.fresh(f,deadline);return Boolean.TRUE.equals(f.get("eligible"));}
 boolean target(Tickets.Actor a,Object user,Object dept){var b=Map.<String,Object>of("sessionToken",a.token(),"targetUserId",user.toString(),"departmentId",dept.toString(),"purpose","TRANSFER");var f=Chain.call("ticket-identity","/internal/identity/ticket-authorizations",b,a.trace(),a.deadline());Chain.fresh(f,a.deadline());return Boolean.TRUE.equals(f.get("eligible"));}
 Map<String,Object> fields(String action,Map<String,Object>b){var required=new HashSet<>(Set.of("expectedVersion","roundId","sourceAssignmentId"));if(action.equals("transfer-request"))required.addAll(Set.of("targetDepartmentId","targetEngineerUserId","reason"));else if(action.equals("transfer-withdraw"))required.add("reason");else{required.add("decision");if("REJECT".equals(b.get("decision")))required.add("reason");}if(!required.equals(b.keySet()))throw Tickets.bad();var out=new TreeMap<String,Object>(b);for(String k:List.of("expectedVersion","targetDepartmentId","targetEngineerUserId"))if(out.containsKey(k)){if(!(out.get(k) instanceof String))throw Tickets.bad();out.put(k,Long.toString(Tickets.id(out.get(k))));}Tickets.uuid(out.get("roundId"));Tickets.uuid(out.get("sourceAssignmentId"));if(out.containsKey("reason"))Tickets.text(out.get("reason"),5,500,true);if(action.equals("transfer-decision")&&(!(out.get("decision") instanceof String)||!Set.of("ACCEPT","REJECT").contains(out.get("decision"))))throw Tickets.bad();return out;}
 @PostMapping("/api/ticket/tickets/{id}/transfer-requests") Map<String,Object> create(@PathVariable String id,@RequestBody Map<String,Object>b,HttpServletRequest r){return perform(id,null,"transfer-request",fields("transfer-request",b),new Workflow(t,access).actor(r),Tickets.uuid(Chain.single(r,"Idempotency-Key")));}
 @PostMapping("/api/ticket/tickets/{id}/transfer-requests/{request}/decision") Map<String,Object> decide(@PathVariable String id,@PathVariable String request,@RequestBody Map<String,Object>b,HttpServletRequest r){var data=fields("transfer-decision",b);data.put("transferRequestId",Tickets.uuid(request));return perform(id,request,"transfer-decision",data,new Workflow(t,access).actor(r),Tickets.uuid(Chain.single(r,"Idempotency-Key")));}
 @PostMapping("/api/ticket/tickets/{id}/transfer-requests/{request}/withdraw") Map<String,Object> withdraw(@PathVariable String id,@PathVariable String request,@RequestBody Map<String,Object>b,HttpServletRequest r){var data=fields("transfer-withdraw",b);data.put("transferRequestId",Tickets.uuid(request));return perform(id,request,"transfer-withdraw",data,new Workflow(t,access).actor(r),Tickets.uuid(Chain.single(r,"Idempotency-Key")));}
 Map<String,Object> perform(String id,String reqId,String action,Map<String,Object>b,Tickets.Actor a,String op){Tickets.uuid(id);String digest=Tickets.hash(b);boolean decision=action.equals("transfer-decision");if(!decision)t.accessible(id,a);
  var result=t.tx.execute(tx->{t.lockActor(a.tenant(),a.user());var rows=t.db.queryForList("SELECT * FROM ticket_record WHERE id=? AND tenant_id=? FOR UPDATE",id,a.tenant());if(rows.isEmpty())throw new Problem(404,"TARGET_NOT_ACCESSIBLE");var row=rows.getFirst();Chain.fresh(Chain.identity("ticket-identity",a.token(),"TICKET_WORK",a.csrf(),a.trace(),a.deadline()),a.deadline());var f=access.facts(a);Map<String,Object> q=decision||reqId!=null?request(reqId):null;
   if(decision){if(!q.get("ticket_id").equals(id))throw new Problem(404,"TARGET_NOT_ACCESSIBLE");recipient(q,a,f);}else{t.accessible(id,a);access.customerService(f,row,"ticket.transfer.request");access.department(f,reqId==null?b.get("targetDepartmentId"):q.get("target_department_id"));}
   var prior=t.db.queryForList("SELECT * FROM ticket_action_operation WHERE operation_id=? FOR UPDATE",op);if(!prior.isEmpty()){var old=prior.getFirst();if(Tickets.id(old.get("tenant_id"))!=a.tenant()||Tickets.id(old.get("actor_user_id"))!=a.user()||!old.get("ticket_id").equals(id))throw new Problem(404,"OPERATION_NOT_FOUND");if(!action.equals(old.get("action"))||!digest.equals(old.get("request_digest")))throw conflict("IDEMPOTENCY_CONFLICT");var receipt=Tickets.json(old.get("result_json"));if(decision&&"ACCEPTED".equals(receipt.get("state"))&&!selfQualified(f,q.get("target_department_id")))throw new Problem(403,"ACCESS_DENIED");return receipt;}
   StockExecutionBoundary.guard(t,id);if(!row.get("round_id").equals(b.get("roundId")))throw conflict("ROUND_CONFLICT");if(!Objects.equals(row.get("assignment_id"),b.get("sourceAssignmentId")))throw conflict("ASSIGNMENT_CONFLICT");if(Tickets.id(row.get("row_version"))!=Tickets.id(b.get("expectedVersion"))||Tickets.id(row.get("row_version"))>=Long.MAX_VALUE-1)throw conflict("VERSION_CONFLICT");t.db.queryForList("SELECT id FROM ticket_assignment WHERE id=? FOR UPDATE",row.get("assignment_id"));var pending=current(row,true);Instant time=now();
   if(reqId!=null&&pending!=null&&!pending.get("id").equals(reqId))throw conflict("TRANSFER_NOT_CURRENT");
   if(pending!=null&&due(pending,time)){expire(row,pending,time);row=new LinkedHashMap<>(row);row.put("current_transfer_id",null);row.put("row_version",Tickets.id(row.get("row_version"))+1);pending=null;if(reqId!=null)return Map.<String,Object>of("expiredFailure",true);}
   if(!active(row))throw conflict("INVALID_STATE");String state,assignment=null;var extra=new LinkedHashMap<String,Object>();
   if(action.equals("transfer-request")){if(row.get("current_cancel_request_id")!=null)throw conflict("CANCELLATION_PENDING");if(pending!=null)throw conflict("TRANSFER_PENDING");if(Tickets.id(row.get("engineer_user_id"))==Tickets.id(b.get("targetEngineerUserId"))||!target(a,b.get("targetEngineerUserId"),b.get("targetDepartmentId")))throw conflict("TARGET_INELIGIBLE");String request=UUID.randomUUID().toString();t.db.update("INSERT INTO ticket_transfer_request(id,ticket_id,tenant_id,round_id,source_assignment_id,source_department_id,source_engineer_user_id,target_department_id,target_engineer_user_id,operation_id,requested_by,reason,requested_at,expires_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",request,id,a.tenant(),row.get("round_id"),row.get("assignment_id"),row.get("department_id"),row.get("engineer_user_id"),Tickets.id(b.get("targetDepartmentId")),Tickets.id(b.get("targetEngineerUserId")),op,a.user(),b.get("reason"),Timestamp.from(time),Timestamp.from(time.plus(Duration.ofHours(24))));t.db.update("UPDATE ticket_record SET current_transfer_id=? WHERE id=?",request,id);q=request(request);state="PENDING_CONFIRMATION";extra.put("requestedAt",time.toString());extra.put("expiresAt",time.plus(Duration.ofHours(24)).toString());
   }else{if(pending==null||!pending.get("id").equals(reqId)||!pending.get("source_assignment_id").equals(row.get("assignment_id"))||end(reqId)!=null)throw conflict("TRANSFER_NOT_CURRENT");q=pending;if(action.equals("transfer-withdraw"))state="WITHDRAWN";else state=b.get("decision").equals("ACCEPT")?"ACCEPTED":"REJECTED";
    if(state.equals("ACCEPTED")){if(row.get("current_cancel_request_id")!=null)throw conflict("CANCELLATION_PENDING");if(!selfQualified(f,q.get("target_department_id")))throw conflict("TARGET_INELIGIBLE");assignment=UUID.randomUUID().toString();t.db.update("INSERT INTO ticket_assignment(id,ticket_id,round_id,tenant_id,department_id,engineer_user_id,assigned_by,note,created_at) VALUES(?,?,?,?,?,?,?,?,?)",assignment,id,row.get("round_id"),a.tenant(),q.get("target_department_id"),q.get("target_engineer_user_id"),a.user(),"TRANSFER_ACCEPTED",Timestamp.from(time));t.db.update("UPDATE ticket_record SET assignment_id=?,department_id=?,engineer_user_id=?,status='IN_PROGRESS' WHERE id=?",assignment,q.get("target_department_id"),q.get("target_engineer_user_id"),id);extra.put("acceptedAt",time.toString());}
    extra.put("decidedAt",time.toString());appendEnd(q,state,b.get("reason"),a.user(),op,assignment,time);if(!state.equals("ACCEPTED"))coordinate(row,q,state.equals("REJECTED")?"TARGET_REJECTED":"REQUEST_WITHDRAWN",time);t.db.update("UPDATE ticket_record SET current_transfer_id=NULL WHERE id=?",id);
   }
   String record=UUID.randomUUID().toString();boolean accepted=state.equals("ACCEPTED");var out=base(row,q,op,action,state,Tickets.id(row.get("row_version"))+1);out.put("assignmentId",accepted?assignment:row.get("assignment_id"));out.put("status",accepted?"IN_PROGRESS":row.get("status"));out.put("recordId",record);out.put("nextAction",state.equals("PENDING_CONFIRMATION")?"WAIT_TRANSFER_DECISION":accepted?"VIEW_TICKET":"COORDINATE_TRANSFER");out.putAll(extra);write(row,a.user(),op,action,out,record,accepted?"工程师交接已完成，现由新工程师继续处理。":"转派请求："+state,accepted,accepted?assignment:row.get("assignment_id"),time,digest);Chain.remaining(a.deadline());return out;
  });if(Boolean.TRUE.equals(result.get("expiredFailure")))throw conflict("TRANSFER_EXPIRED");return result;
 }
 Map<String,Object> base(Map<String,Object>row,Map<String,Object>q,String op,String action,String state,long version){var out=new LinkedHashMap<String,Object>();out.putAll(Map.of("operationId",op,"action",action,"state",state,"transferRequestId",q.get("id"),"ticketId",row.get("id"),"roundId",q.get("round_id"),"sourceAssignmentId",q.get("source_assignment_id"),"rowVersion",Long.toString(version)));for(String[]p:new String[][]{{"sourceDepartmentId","source_department_id"},{"sourceEngineerUserId","source_engineer_user_id"},{"targetDepartmentId","target_department_id"},{"targetEngineerUserId","target_engineer_user_id"}})out.put(p[0],q.get(p[1]).toString());return out;}
 void write(Map<String,Object>row,long actor,String op,String action,Map<String,Object>out,String record,String body,boolean visible,Object assignment,Instant time,String digest){String id=row.get("id").toString();long version=Tickets.id(row.get("row_version"))+1;t.db.update("INSERT INTO ticket_processing_record(id,ticket_id,round_id,assignment_id,operation_id,actor_user_id,type,body,work_hours,visibility,qualification_json,row_version,occurred_at) VALUES(?,?,?,?,?,?,?,?,0,?,?,?,?)",record,id,row.get("round_id"),assignment,op,actor,action.toUpperCase(Locale.ROOT).replace('-','_'),body,visible?"CUSTOMER_VISIBLE":"INTERNAL",actor==0?"{\"identityType\":\"SYSTEM\",\"purpose\":\"TRANSFER_SCAN\"}":"{\"identityType\":\"EMPLOYEE\"}",version,Timestamp.from(time));t.db.update("UPDATE ticket_record SET row_version=row_version+1 WHERE id=?",id);t.db.update("INSERT INTO ticket_action_operation(operation_id,tenant_id,actor_user_id,ticket_id,action,request_digest,result_json,created_at) VALUES(?,?,?,?,?,?,?,?)",op,row.get("tenant_id"),actor,id,action,digest,Chain.JSON.writeValueAsString(out),Timestamp.from(time));t.db.update("INSERT INTO ticket_audit(operation_id,tenant_id,actor_user_id,action,occurred_at) VALUES(?,?,?,?,?)",op,row.get("tenant_id"),actor,"WORKFLOW_"+action.toUpperCase(Locale.ROOT).replace('-','_'),Timestamp.from(time));}
 void appendEnd(Map<String,Object>q,String state,Object reason,Long actor,String op,Object assignment,Instant time){t.db.update("INSERT INTO ticket_transfer_end(request_id,ticket_id,round_id,operation_id,state,reason,decided_by,decided_at,assignment_id) VALUES(?,?,?,?,?,?,?,?,?)",q.get("id"),q.get("ticket_id"),q.get("round_id"),op,state,reason,actor,Timestamp.from(time),assignment);}
 void coordinate(Map<String,Object>row,Map<String,Object>q,String reason,Instant time){String key=stable(reason+":"+(q==null?row.get("assignment_id"):q.get("id")));if(t.db.queryForObject("SELECT COUNT(*) FROM ticket_coordination_event WHERE id=?",Long.class,key)>0)return;t.db.update("INSERT INTO ticket_coordination_event(id,ticket_id,round_id,assignment_id,reason,request_id,created_at) VALUES(?,?,?,?,?,?,?)",key,row.get("id"),row.get("round_id"),row.get("assignment_id"),reason,q==null?null:q.get("id"),Timestamp.from(time));}
 void terminate(Map<String,Object>row,Tickets.Actor a,String op,String reason,Instant time){var q=current(row,true);if(q==null)return;appendEnd(q,"NO_LONGER_APPLICABLE",reason,a.user(),op,null,time);t.db.update("UPDATE ticket_record SET current_transfer_id=NULL WHERE id=?",row.get("id"));t.db.update("INSERT INTO ticket_audit(operation_id,tenant_id,actor_user_id,action,occurred_at) VALUES(?,?,?,'TRANSFER_NO_LONGER_APPLICABLE',?)",op,a.tenant(),a.user(),Timestamp.from(time));}
 void expire(Map<String,Object>row,Map<String,Object>q,Instant time){String op=stable("transfer-expire:"+q.get("id"));appendEnd(q,"EXPIRED","TRANSFER_EXPIRED",null,op,null,time);coordinate(row,q,"TRANSFER_EXPIRED",time);t.db.update("UPDATE ticket_record SET current_transfer_id=NULL WHERE id=?",row.get("id"));var out=base(row,q,op,"transfer-expire","EXPIRED",Tickets.id(row.get("row_version"))+1);out.put("status",row.get("status"));out.put("expiredAt",time.toString());write(row,0,op,"transfer-expire",out,UUID.randomUUID().toString(),"转派请求已超时，需协调交接。",false,row.get("assignment_id"),time,Tickets.hash(out));}
 Map<String,Object> narrowReceipt(Map<String,Object>op,Tickets.Actor a){var result=Tickets.json(op.get("result_json"));var q=request(result.get("transferRequestId"));var f=access.facts(a);recipient(q,a,f);if("ACCEPTED".equals(result.get("state"))&&!selfQualified(f,q.get("target_department_id")))throw new Problem(403,"ACCESS_DENIED");var out=new LinkedHashMap<String,Object>();for(String k:List.of("operationId","action","transferRequestId","ticketId","roundId","sourceAssignmentId","state","status","rowVersion","assignmentId","acceptedAt","decidedAt","nextAction","sourceDepartmentId","sourceEngineerUserId","targetDepartmentId","targetEngineerUserId"))if(result.containsKey(k))out.put(k,result.get(k));return out;}
 Map<String,Object> view(Map<String,Object>q,boolean customer){var out=new LinkedHashMap<String,Object>();for(String[]p:new String[][]{{"transferRequestId","id"},{"ticketId","ticket_id"},{"roundId","round_id"},{"sourceAssignmentId","source_assignment_id"},{"sourceDepartmentId","source_department_id"},{"sourceEngineerUserId","source_engineer_user_id"},{"targetDepartmentId","target_department_id"},{"targetEngineerUserId","target_engineer_user_id"}})out.put(p[0],q.get(p[1]).toString());out.put("requestedAt",Tickets.utc(q.get("requested_at")));out.put("expiresAt",Tickets.utc(q.get("expires_at")));if(!customer)out.put("reason",q.get("reason"));var e=end(q.get("id"));out.put("state",e==null?"PENDING_CONFIRMATION":e.get("state"));var decision=new LinkedHashMap<String,Object>();if(e!=null){decision.put("state",e.get("state"));decision.put("decidedBy",e.get("decided_by")==null?null:e.get("decided_by").toString());decision.put("decidedAt",Tickets.utc(e.get("decided_at")));decision.put("assignmentId",e.get("assignment_id"));if(!customer)decision.put("reason",e.get("reason"));}out.put("decision",e==null?null:decision);return out;}
 static long[] page(HttpServletRequest r,Set<String>keys){for(var p:r.getParameterMap().entrySet())if(!keys.contains(p.getKey())||p.getValue().length!=1)throw Tickets.bad();long page=r.getParameter("page")==null?1:Tickets.id(r.getParameter("page")),size=r.getParameter("size")==null?20:Tickets.id(r.getParameter("size"));if(page>1000000||!Set.of(20L,50L,100L).contains(size))throw Tickets.bad();return new long[]{page,size};}
 Map<String,Object> inboxView(Map<String,Object>q,Map<String,Object>f){var row=t.db.queryForMap("SELECT * FROM ticket_record WHERE id=?",q.get("ticket_id"));var out=view(q,false);out.remove("decision");out.put("ticketNo",row.get("ticket_no"));out.put("rowVersion",row.get("row_version").toString());out.put("status",row.get("status"));boolean expired=end(q.get("id"))==null&&due(q,now());out.put("effectiveState",expired?"EXPIRED":out.get("state"));out.put("expiredAtPending",expired);String description=row.get("description").toString();int limit=description.offsetByCodePoints(0,Math.min(200,description.codePointCount(0,description.length())));var snapshot=Tickets.json(row.get("snapshot_json"));out.put("handoffSummary",Map.of("title",row.get("title"),"deviceName",snapshot.getOrDefault("deviceName",row.get("device_id").toString()),"faultSummary",description.substring(0,limit)));out.put("allowedActions",!expired&&out.get("state").equals("PENDING_CONFIRMATION")&&Objects.equals(row.get("current_transfer_id"),q.get("id"))?(selfQualified(f,q.get("target_department_id"))?List.of("transfer-accept","transfer-reject"):List.of("transfer-reject")):List.of());return out;}
 @GetMapping("/api/ticket/transfer-inbox") Map<String,Object> inbox(HttpServletRequest r){var a=t.actor(r,false);var f=access.facts(a);if(f.get("departmentId")==null||!receivable(f,f.get("departmentId")))throw new Problem(403,"ACCESS_DENIED");var p=page(r,Set.of("page","size"));String where=" FROM ticket_transfer_request q JOIN ticket_record r ON r.current_transfer_id=q.id WHERE q.tenant_id=? AND q.target_engineer_user_id=? AND q.target_department_id=? AND q.expires_at>? AND NOT EXISTS(SELECT 1 FROM ticket_transfer_end e WHERE e.request_id=q.id)";var time=Timestamp.from(now());long total=t.db.queryForObject("SELECT COUNT(*)"+where,Long.class,a.tenant(),a.user(),Tickets.id(f.get("departmentId")),time);return Map.of("items",t.db.queryForList("SELECT q.*"+where+" ORDER BY q.requested_at,q.id LIMIT ? OFFSET ?",a.tenant(),a.user(),Tickets.id(f.get("departmentId")),time,p[1],(p[0]-1)*p[1]).stream().map(q->inboxView(q,f)).toList(),"total",total,"page",p[0],"size",p[1]);}
 @GetMapping("/api/ticket/transfer-inbox/{id}") Map<String,Object> inboxDetail(@PathVariable String id,HttpServletRequest r){if(!r.getParameterMap().isEmpty())throw Tickets.bad();var a=t.actor(r,false);var f=access.facts(a);var q=request(Tickets.uuid(id));recipient(q,a,f);return inboxView(q,f);}
 @GetMapping("/api/ticket/tickets/{id}/transfer-requests") Map<String,Object> history(@PathVariable String id,HttpServletRequest r){var a=t.actor(r,false);var visible=t.accessible(id,a);String selectedRound=new Rounds(t).selected(r,visible);var p=page(r,Set.of("page","size","roundId"));String where="ticket_id=? AND round_id=?"+(a.type().equals("CUSTOMER")?" AND id IN(SELECT request_id FROM ticket_transfer_end WHERE state='ACCEPTED')":"");return Map.of("items",t.db.queryForList("SELECT * FROM ticket_transfer_request WHERE "+where+" ORDER BY requested_at DESC,id DESC LIMIT ? OFFSET ?",id,selectedRound,p[1],(p[0]-1)*p[1]).stream().map(q->view(q,a.type().equals("CUSTOMER"))).toList(),"total",t.db.queryForObject("SELECT COUNT(*) FROM ticket_transfer_request WHERE "+where,Long.class,id,selectedRound),"page",p[0],"size",p[1]);}
 @GetMapping("/api/ticket/tickets/{id}/transfer-candidates") Map<String,Object> candidates(@PathVariable String id,HttpServletRequest r){var a=t.actor(r,false);var row=t.accessible(id,a);var f=access.facts(a);access.customerService(f,row,"ticket.transfer.request");page(r,Set.of("departmentId","keyword","page","size"));String department=Long.toString(Tickets.id(r.getParameter("departmentId")));access.department(f,department);var b=new HashMap<String,Object>();b.put("sessionToken",a.token());b.put("departmentId",department);b.put("purpose","TRANSFER");b.put("excludeUserId",row.get("engineer_user_id"));for(String p:List.of("keyword","page","size"))if(r.getParameter(p)!=null)b.put(p,r.getParameter(p));var result=Chain.call("ticket-identity","/internal/identity/ticket-candidates",b,a.trace(),a.deadline());Chain.fresh(result,a.deadline());return result;}
 Map<String,Object> coordination(Map<String,Object>row){if(!coordinationActive(row))return Map.of("required",false,"reasons",List.of(),"sourceQualified",true);boolean qualified=sourceQualified(row);var reasons=new ArrayList<>(t.db.queryForList("SELECT DISTINCT reason FROM ticket_coordination_event WHERE ticket_id=? AND assignment_id=? ORDER BY reason",String.class,row.get("id"),row.get("assignment_id")));if(!qualified&&!reasons.contains("SOURCE_INELIGIBLE"))reasons.add("SOURCE_INELIGIBLE");var out=new LinkedHashMap<String,Object>();out.put("required",!reasons.isEmpty());out.put("reasons",reasons);out.put("sourceQualified",qualified);out.put("pendingRequestId",row.get("current_transfer_id"));return out;}
 Map<String,Object> coordinationList(String where,List<Object>args,long page,long size,Tickets.Actor a){var f=access.facts(a);if(!access.permission(f,"ticket.transfer.request")||!access.permission(f,"ticket.read"))throw new Problem(403,"ACCESS_DENIED");var rows=t.db.queryForList("SELECT r.* FROM ticket_record r WHERE "+where+" AND r.status IN('ASSIGNED','IN_PROGRESS','WAITING_INFORMATION','PENDING_CUSTOMER_CONFIRMATION') ORDER BY r.submitted_at DESC,r.id DESC LIMIT 1001",args.toArray());if(rows.size()>1000)throw new Problem(503,"COORDINATION_QUERY_LIMIT");var items=new ArrayList<Map<String,Object>>();for(var row:rows){if(!access.company(f,row.get("company_id")))continue;var c=coordination(row);if(Boolean.TRUE.equals(c.get("required"))){var item=t.summary(row);item.put("transferCoordination",c);items.add(item);}}long from=Math.min(items.size(),(page-1)*size),to=Math.min(items.size(),from+size);return Map.of("items",items.subList((int)from,(int)to),"total",items.size(),"page",page,"size",size);}
 void project(Map<String,Object>out,Map<String,Object>row,Tickets.Actor a){if(a.type().equals("CUSTOMER")){out.put("currentEngineerUserId",row.get("engineer_user_id")==null?null:row.get("engineer_user_id").toString());out.put("currentDepartmentId",row.get("department_id")==null?null:row.get("department_id").toString());out.put("transferHistory",t.db.queryForList("SELECT * FROM ticket_transfer_request WHERE ticket_id=? AND id IN(SELECT request_id FROM ticket_transfer_end WHERE state='ACCEPTED') ORDER BY requested_at,id",row.get("id")).stream().map(q->view(q,true)).toList());return;}var q=current(row,false);out.put("currentTransfer",q==null?null:view(q,false));var f=access.facts(a);var actions=new ArrayList<String>((List<String>)out.get("allowedActions"));if(access.company(f,row.get("company_id"))&&access.permission(f,"ticket.transfer.request")){out.put("transferCoordination",coordination(row));out.put("transferDepartments",f.get("assignableDepartments"));if(active(row)&&row.get("current_cancel_request_id")==null){if(q==null||due(q,now()))actions.add("transfer-request");if(q!=null&&((List<?>)f.get("assignableDepartmentIds")).contains(q.get("target_department_id").toString()))actions.add("transfer-withdraw");}}else out.put("transferCoordination",null);out.put("allowedActions",actions);}
 public int scanAt(Instant time){int changed=0;for(var q:t.db.queryForList("SELECT q.* FROM ticket_transfer_request q JOIN ticket_record r ON r.current_transfer_id=q.id WHERE q.expires_at<=? AND NOT EXISTS(SELECT 1 FROM ticket_transfer_end e WHERE e.request_id=q.id) ORDER BY q.expires_at,q.id LIMIT 50",Timestamp.from(time))){try{Boolean done=t.tx.execute(tx->{t.lockActor(Tickets.id(q.get("tenant_id")),0);var row=t.db.queryForMap("SELECT * FROM ticket_record WHERE id=? FOR UPDATE",q.get("ticket_id"));if(!Objects.equals(row.get("current_transfer_id"),q.get("id"))||end(q.get("id"))!=null)return false;t.db.queryForList("SELECT id FROM ticket_assignment WHERE id=? FOR UPDATE",row.get("assignment_id"));current(row,true);if(!due(q,time))return false;expire(row,q,time);return true;});if(Boolean.TRUE.equals(done))changed++;}catch(RuntimeException e){System.err.println("transfer.scan failure request="+q.get("id")+" type="+e.getClass().getSimpleName());}}return changed;}

 boolean coordinationActive(Map<String,Object>r){return r.get("assignment_id")!=null&&Set.of("ASSIGNED","IN_PROGRESS","WAITING_INFORMATION","PENDING_CUSTOMER_CONFIRMATION").contains(r.get("status"));}
 public boolean scanOwner(String id){var rows=t.db.queryForList("SELECT * FROM ticket_record WHERE id=?",Tickets.uuid(id));if(rows.isEmpty()||!coordinationActive(rows.getFirst())||sourceQualified(rows.getFirst()))return false;var row=rows.getFirst();return Boolean.TRUE.equals(t.tx.execute(tx->{t.lockActor(Tickets.id(row.get("tenant_id")),0);var locked=t.db.queryForMap("SELECT * FROM ticket_record WHERE id=? FOR UPDATE",id);if(!coordinationActive(locked)||!Objects.equals(locked.get("assignment_id"),row.get("assignment_id")))return false;String event=stable("SOURCE_INELIGIBLE:"+locked.get("assignment_id"));if(t.db.queryForObject("SELECT COUNT(*) FROM ticket_coordination_event WHERE id=?",Long.class,event)>0||sourceQualified(locked))return false;coordinate(locked,null,"SOURCE_INELIGIBLE",now());String op=stable("coordinate:"+event);var out=new LinkedHashMap<String,Object>();out.put("state","COORDINATION_REQUIRED");out.put("ticketId",locked.get("id"));write(locked,0,op,"transfer-coordinate",out,UUID.randomUUID().toString(),"当前负责人资格失效，需协调交接。",false,locked.get("assignment_id"),now(),Tickets.hash(out));return true;}));}
 String scanCursor="";
 public int scanOwners(){var rows=t.db.queryForList("SELECT id FROM ticket_record WHERE status IN('ASSIGNED','IN_PROGRESS','WAITING_INFORMATION','PENDING_CUSTOMER_CONFIRMATION') AND assignment_id IS NOT NULL AND id>? ORDER BY id LIMIT 25",scanCursor);if(rows.isEmpty()){scanCursor="";return 0;}int changed=0;for(var row:rows){scanCursor=row.get("id").toString();try{if(scanOwner(scanCursor))changed++;}catch(RuntimeException e){System.err.println("transfer.owner-scan failure ticket="+scanCursor+" type="+e.getClass().getSimpleName());}}return changed;}
}
